def left_truncate_path(path, maxlen):
    if len(path) <= maxlen:
        return path
    keep = maxlen - 3
    if keep <= 0:
        return '...'[:maxlen]
    return '...' + path[-keep:]

import re

def is_valid_domain_name(s):
    labels = s.split('.')
    if len(labels) < 2:
        return False
    for label in labels:
        if not (1 <= len(label) <= 63):
            return False
        if not re.fullmatch(r'[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?', label):
            return False
    tld = labels[-1]
    if not tld.isalpha() or len(tld) < 2:
        return False
    return True

def char_difference_count(s1, s2):
    if len(s1) != len(s2):
        return -1
    return sum(1 for a, b in zip(s1, s2) if a != b)

def frequency_rank_map(items):
    counts = {}
    for it in items:
        counts[it] = counts.get(it, 0) + 1
    distinct_in_order = list(counts.keys())
    ranked = sorted(distinct_in_order, key=lambda x: -counts[x])
    return {val: i + 1 for i, val in enumerate(ranked)}

