import datetime

def week_start_date(year, month, day):
    d = datetime.date(year, month, day)
    monday = d - datetime.timedelta(days=d.weekday())
    return (monday.year, monday.month, monday.day)

def is_valid_sudoku_box(box):
    if len(box) != 9:
        return False
    seen = set()
    for v in box:
        if v != 0:
            if not (1 <= v <= 9):
                return False
            if v in seen:
                return False
            seen.add(v)
    return True

def count_valleys(lst):
    if len(lst) < 3:
        return 0
    count = 0
    for i in range(1, len(lst) - 1):
        if lst[i] < lst[i-1] and lst[i] < lst[i+1]:
            count += 1
    return count

